using System;using System.Collections;using System.IO;using System.Text;using UnityEngine;using UnityEngine.AI;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckSheepHerding
{
 public sealed class HerdProbe:MonoBehaviour
 {
  public static bool SkillOnly;const string Folder="Logs/TruckSports/EighteenSports/Herd";IDisposable preferences;readonly StringBuilder report=new StringBuilder();int checks,errors;HerdMatch watched;Gamepad pad;InputSettings.BackgroundBehavior background;bool intentionalPause;float scale=1,watchdog;
#if UNITY_EDITOR
  InputSettings.EditorInputBehaviorInPlayMode editorInput;
#endif
  [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsHerd")>=0;
#if UNITY_EDITOR
   SkillOnly=UnityEditor.SessionState.GetBool("Sports.Herd.Skill",false);UnityEditor.SessionState.SetBool("Sports.Herd.Skill",false);run|=UnityEditor.SessionState.GetBool("Sports.Herd.Probe",false);UnityEditor.SessionState.SetBool("Sports.Herd.Probe",false);
#endif
   if(run){var go=new GameObject("Explicit actual sheep herding acceptance");DontDestroyOnLoad(go);go.AddComponent<SportsProbeInputIsolation>();go.AddComponent<HerdProbe>();}}
  void Awake(){preferences=SportsPrefs.IsolateValidation("Herd");SportsParticipantRegistry.ForgetCache();background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;
#if UNITY_EDITOR
   editorInput=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
#endif
  }
  void Update(){if(watchdog>0&&Time.realtimeSinceStartup>watchdog){watchdog=0;Check(false,"bounded farm acceptance watchdog expired");watched?.SetupScreen();StopAllCoroutines();Complete();}if(watched!=null&&watched.Running&&!watched.Finished&&!intentionalPause&&watched.Paused&&watched.DevicesReady){report.AppendLine("HARNESS_ACKNOWLEDGED_EXTERNAL_PAUSE focused="+Application.isFocused);watched.Resume();Time.timeScale=scale;}}
  void Check(bool ok,string message){checks++;if(!ok)errors++;report.AppendLine((ok?"PASS ":"FAIL ")+message);File.WriteAllText(Folder+"/progress.txt",report.ToString());}
  void Error(string m,string stack,LogType t){if(t==LogType.Error||t==LogType.Exception){errors++;report.AppendLine("ERROR "+m+"\n"+stack);}}
  IEnumerator Start()
  {
   watchdog=Time.realtimeSinceStartup+480;Directory.CreateDirectory(Folder);File.WriteAllText(Folder+"/result.txt","RUNNING");Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<HerdMatch>("TruckSheepHerding");yield return null;var m=FindAnyObjectByType<HerdMatch>();watched=m;Check(m!=null&&m.sheep.Length==48&&m.pens.Length==4&&m.trucks.Length==4,"saved farm contains full NWH trucks, genuine SheepV5 flock and four physically open pens");if(m==null){Complete();yield break;}var audio=m.GetComponent<SportsMatchAudioAnchor>();Check(audio!=null&&audio.listener!=null&&audio.listener.transform!=m.transform&&FindObjectsByType<AudioListener>(FindObjectsInactive.Exclude).Length==1,"existing single viewport audio anchor is bound separately from simulation authority");
   var clear=Array.Find(m.atmosphere.presets.entries,x=>x.legacyKind==SportsWeatherKind.Clear);if(clear!=null)m.atmosphere.presets.Select(clear.id);if(SkillOnly){yield return Skills(m);m.SetupScreen();Complete();yield break;}m.setup.count=4;m.AllBots();m.option=1;SportsCameraOptions.Set(false);m.drivingViews.Select(0);foreach(var t in m.trucks){t.tractorMotor.vehicle.powertrain.engine.Damage=1;t.tractorMotor.vehicle.powertrain.transmission.Damage=.9f;t.wheels[0].Damage=.8f;}Check(m.StartMatch(),"default three-minute four-AI farm competition starts");bool repaired=Array.TrueForAll(m.trucks,t=>t.tractorMotor.vehicle.powertrain.engine.Damage==0&&t.tractorMotor.vehicle.powertrain.transmission.Damage==0&&t.wheels[0].Damage==0);Check(repaired,"real rematch repairs deliberately damaged NWH engines, transmissions and tyres through the vendor API");if(!repaired){m.SetupScreen();Complete();yield break;}yield return new WaitForSeconds(1.5f);bool grounded=!m.rules.Live;foreach(var sheep in m.sheep){var motion=sheep.GetComponentInChildren<SportsSheepMotion>();grounded&=sheep.agent.isOnNavMesh&&motion!=null&&motion.animator!=null&&motion.animator.runtimeAnimatorController!=null&&Vector3.Distance(sheep.body.position,sheep.agent.nextPosition)<.15f;}Check(grounded,"every actual rig is grounded on baked farm navigation and has existing idle/walk animation");
   bool paths=true;foreach(var pen in m.pens){var path=new NavMeshPath();paths&=NavMesh.CalculatePath(Vector3.zero,pen.transform.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;}Check(paths,"all four real pen interiors are reachable through their visible openings");
   scale=Time.timeScale=4;float end=Time.realtimeSinceStartup+210,next=0;bool scoreCaptured=false,paused=false,captured=false;
   while(!m.Finished&&Time.realtimeSinceStartup<end)
   {
                if(!scoreCaptured&&m.ScoreJournal.Count>0){scoreCaptured=true;yield return SportsScoreAcceptance.CaptureAward(m,Check,Folder);if(SportsScoreAcceptance.CaptureOnly){SportsScoreAcceptance.Journal(m,m.ActualSecured,Check);Check(true,"focused first-award capture; full-match evidence is recorded separately");m.SetupScreen();Check(m.StartMatch()&&m.ScoreJournal.Count==0,"focused scoring rematch starts with an empty journal");yield return null;m.SetupScreen();Complete();yield break;}}

    if(!paused&&m.rules.Clock>3){paused=true;intentionalPause=true;var clock=m.rules.Clock;var p=m.sheep[0].body.position;m.Pause();yield return new WaitForSecondsRealtime(.2f);Check(clock==m.rules.Clock&&p==m.sheep[0].body.position,"pause stops timer and actual NavMesh sheep movement");m.Resume();intentionalPause=false;Time.timeScale=4;}
    if(!captured&&m.rules.Clock>15){captured=true;yield return SportsWindowCapture.Save(1280,720,Folder+"/gameplay-720.png");yield return SportsWindowCapture.Save(1920,1080,Folder+"/gameplay-1080.png");}
    if(Time.realtimeSinceStartup>=next){next=Time.realtimeSinceStartup+10;report.AppendLine("ACTUAL_HERD t="+m.rules.Clock+" secured="+m.ActualSecured+" points="+string.Join(",",m.rules.points)+" horns="+m.HornReactions+" truckThreats="+m.TruckThreats+" explosions="+m.ActualExplosions);File.WriteAllText(Folder+"/progress.txt",report.ToString());}yield return null;
   }
   scale=Time.timeScale=1;SportsScoreAcceptance.Journal(m,m.ActualSecured,Check);Check(scoreCaptured,"actual award animation captured at720p/1080p");Check(m.Finished&&m.rules.Complete,"actual full timed farm competition reaches final standings");Check(m.ActualSecured>=4,"contested AI match genuinely herds multiple sheep through physical pen entries");Check(m.HornReactions>0&&m.TruckThreats>0,"actual flock behavior responds to AI truck positioning and meaningful horn pressure");int sum=0;foreach(int score in m.rules.points)sum+=score;Check(sum==m.ActualSecured,"one-time secured animal identities match the scoreboard exactly");if(m.Finished){yield return SportsResultsAcceptance.Capture(m,Check,Folder,m.rules.Place,slot=>(double?)m.rules.points[slot]);var before=m.Results;m.ExtraAction("watchherd");yield return new WaitForSecondsRealtime(.25f);Check(m.review.Playing,"actual animated flock and truck recorded review starts");yield return SportsWindowCapture.Save(1280,720,Folder+"/replay-720.png");m.ExtraAction("replayskip");Check(before==m.Results&&!m.review.Playing,"review cannot change final herd counts or completion times");}
   pad=InputSystem.AddDevice<Gamepad>("Actual horn and pen contact fixture");yield return HumanHerd(m);m.SetupScreen();if(pad!=null&&pad.added)InputSystem.RemoveDevice(pad);pad=null;yield return Skills(m);yield return SportsExpansionCameraAcceptance.Run(m,m.drivingViews,Check,Folder);
   m.SetupScreen();m.setup.count=4;m.AllBots();Check(m.StartMatch()&&m.ActualSecured==0&&Array.TrueForAll(m.sheep,s=>s.gameObject.activeSelf&&s.agent.isOnNavMesh)&&Array.TrueForAll(m.looseFences,f=>f.isKinematic),"rematch restores full flock, unclaimed identities, explosive sheep and knocked fences");m.SetupScreen();Complete();
  }
  IEnumerator HumanHerd(HerdMatch m)
  {
   m.SetupScreen();m.setup.count=1;m.AllBots();m.setup.players[0].source=BowlingSource.WholeController;m.setup.players[0].pad=pad;InputSystem.QueueStateEvent(pad,new GamepadState());Check(m.StartMatch(),"controlled actual human horn/herding fixture starts");while(m.Countdown>0)yield return null;var animal=Array.Find(m.sheep,s=>!s.explosive);var hazard=Array.Find(m.sheep,s=>s.explosive);foreach(var s in m.sheep)if(s!=animal&&s!=hazard){s.Stop();s.gameObject.SetActive(false);}hazard.Stop();hazard.gameObject.SetActive(false);var pen=m.pens[0];var outside=pen.transform.position-pen.transform.forward*20;animal.ResetSheep(outside,pen.transform.rotation);m.trucks[0].Prepare(outside-pen.transform.forward*17+Vector3.up*.65f,pen.transform.rotation);Physics.SyncTransforms();yield return new WaitForSeconds(.4f);InputSystem.QueueStateEvent(pad,new GamepadState{rightTrigger=.4f}.WithButton(GamepadButton.LeftStick));float limit=Time.realtimeSinceStartup+20;while(m.ActualSecured==0&&Time.realtimeSinceStartup<limit)yield return null;InputSystem.QueueStateEvent(pad,new GamepadState());Check(m.ActualSecured==1&&m.rules.owners[animal.id]==0&&m.pens[0].ContainsWhole(animal),"actual assigned driving and horn pressure guide a whole animated sheep through the visible pen opening");Check(m.HornReactions>0,"dedicated actual human horn input affects the flock without adding points");int score=m.rules.points[0];yield return new WaitForSeconds(1);Check(score==m.rules.points[0]&&!m.Secure(animal,0),"continued or repeated pen contact never scores the same animal twice");
   animal.Stop();animal.gameObject.SetActive(false);hazard.ResetSheep(new Vector3(37,0,-38),Quaternion.identity);m.trucks[0].Prepare(new Vector3(37,.65f,-50),Quaternion.identity);m.trucks[0].tractorMotor.AddAssemblyVelocity(Vector3.forward*12);Physics.SyncTransforms();limit=Time.realtimeSinceStartup+6;while(m.ActualExplosions==0&&Time.realtimeSinceStartup<limit)yield return null;Check(m.ActualExplosions==1&&m.rules.detonated[hazard.id]&&!hazard.gameObject.activeSelf,"actual marked-sheep truck impact triggers its delayed bounded explosion once");Check(m.rules.points[0]==score&&Array.Exists(m.looseFences,f=>!f.isKinematic),"explosive sheep awards no herd points and physically knocks a nearby lightweight fence loose");m.SetupScreen();
  }
  IEnumerator Skills(HerdMatch m)
  {
   var devices=new Gamepad[4];for(int i=0;i<4;i++)devices[i]=InputSystem.AddDevice<Gamepad>("Isolated AI capability neutral driver "+i);
   for(int tested=0;tested<4;tested++)
   {
    m.SetupScreen();m.setup.count=4;m.AllBots();for(int slot=0;slot<4;slot++)if(slot!=tested){m.setup.players[slot].source=BowlingSource.WholeController;m.setup.players[slot].pad=devices[slot];InputSystem.QueueStateEvent(devices[slot],new GamepadState());}m.trucks[tested].tractorMotor.vehicle.powertrain.engine.Damage=.98f;m.trucks[tested].tractorMotor.vehicle.powertrain.transmission.Damage=.9f;m.trucks[tested].wheels[0].Damage=.8f;Check(m.StartMatch(),"isolated physical AI pen capability starts slot="+tested);Check(m.trucks[tested].tractorMotor.vehicle.powertrain.engine.Damage==0&&m.trucks[tested].tractorMotor.vehicle.powertrain.transmission.Damage==0&&m.trucks[tested].wheels[0].Damage==0,"AI slot begins rematch with repaired real NWH powertrain and tyres slot="+tested);while(m.Countdown>0)yield return null;var animal=Array.Find(m.sheep,x=>!x.explosive);foreach(var other in m.sheep)if(other!=animal){other.Stop();other.gameObject.SetActive(false);}var pen=m.pens[tested];animal.ResetSheep(pen.transform.position-pen.transform.forward*20,pen.transform.rotation);var start=pen.transform.position-pen.transform.forward*39;if(NavMesh.SamplePosition(start,out var ground,4,NavMesh.AllAreas))start=ground.position;m.trucks[tested].Prepare(start+Vector3.up*.65f,pen.transform.rotation);Physics.SyncTransforms();float limit=Time.realtimeSinceStartup+25,nextTrace=0;while(m.ActualSecured==0&&Time.realtimeSinceStartup<limit){if(Time.realtimeSinceStartup>=nextTrace){nextTrace=Time.realtimeSinceStartup+1;var truck=m.trucks[tested];report.AppendLine("SKILL_TRACE slot="+tested+" clock="+m.rules.Clock+" truck="+truck.body.position+" forward="+truck.transform.forward+" speed="+truck.body.linearVelocity+" drive="+truck.command+" engine="+truck.tractorMotor.vehicle.powertrain.engine.IsRunning+" gear="+truck.tractorMotor.vehicle.powertrain.transmission.Gear+" engineRPM="+truck.tractorMotor.vehicle.powertrain.engine.OutputRPM+" torque="+truck.tractorMotor.vehicle.powertrain.engine.outputTorque+" engineDamage="+truck.tractorMotor.vehicle.powertrain.engine.Damage+" clutchDamage="+truck.tractorMotor.vehicle.powertrain.clutch.Damage+" engineActive="+truck.tractorMotor.vehicle.powertrain.engine.IsActive+" clutchActive="+truck.tractorMotor.vehicle.powertrain.clutch.IsActive+" lod="+truck.tractorMotor.vehicle.activeLODIndex+" cameraDistance="+truck.tractorMotor.vehicle.vehicleToCamDistance+" brake="+truck.tractorMotor.vehicle.input.states.brakes+" handbrake="+truck.tractorMotor.vehicle.input.states.handbrake+" sheep="+animal.body.position+" goal="+animal.RequestedGoal+" navSpeed="+animal.agent.velocity+" horn="+truck.tractorMotor.vehicle.input.states.horn);File.WriteAllText(Folder+"/progress.txt",report.ToString());}yield return null;}if(m.ActualSecured==0)yield return SportsWindowCapture.Save(1280,720,Folder+"/failed-ai-slot-"+tested+".png");report.AppendLine("ISOLATED_AI_PEN slot="+tested+" truck="+m.trucks[tested].body.position+" sheep="+animal.body.position+" owner="+m.rules.owners[animal.id]+" points="+string.Join(",",m.rules.points));Check(m.ActualSecured==1&&m.rules.points[tested]==1&&m.rules.owners[animal.id]==tested&&pen.ContainsWhole(animal),"this AI slot genuinely drives and herds the whole animal into its assigned pen slot="+tested);
   }
   m.SetupScreen();foreach(var device in devices)if(device!=null&&device.added)InputSystem.RemoveDevice(device);
  }
  void Complete(){report.AppendLine("CHECKS="+checks+" ERRORS="+errors+"; platform="+Application.platform+"; capture="+SportsWindowCapture.EvidenceKind+"; actual NWH/NavMesh sheep, horn and pen contacts plus software input. No physical devices, subjective listening or human-playtest certification.");File.WriteAllText(Folder+"/result.txt",report.ToString());Application.logMessageReceived-=Error;
#if UNITY_EDITOR
   if(Application.isEditor)UnityEditor.EditorApplication.isPlaying=false;else
#endif
   Application.Quit(errors==0?0:2);}
  void OnDestroy(){Application.logMessageReceived-=Error;if(pad!=null&&pad.added)InputSystem.RemoveDevice(pad);InputSystem.settings.backgroundBehavior=background;
#if UNITY_EDITOR
   InputSystem.settings.editorInputBehaviorInPlayMode=editorInput;
#endif
   preferences?.Dispose();SportsParticipantRegistry.ForgetCache();Time.timeScale=1;}
 }
